"""Generate portable GitHub Pages HTML from the curated repository catalog."""
from pathlib import Path
from html import escape
from attendee_content import ROBOTICS, ATTENDEE, ABOUT, attendee_intro, robotics_zones

ROOT = Path(__file__).resolve().parents[1]
ORG = 'https://github.com/ExMachinaParlor/'
RANGES = [
 dict(slug='active-directory', title='Active Directory', repo='EMP-AD-Range', category='Enterprise / Ludus', summary='A six-machine enterprise lab: two domain controllers, a departmental file server, two Windows workstations, and a Debian web server.', label='Ludus deployment', facts=[('Platform','Ludus'),('Environment','Windows Server 2022 / Windows 11 / Debian 12'),('Topology','6 virtual machines / 3 VLANs')], sections=[('Inside the range','Explore the emprange.net domain across server, workstation, and DMZ networks. The repository includes a Ludus configuration, custom Ansible roles, a network diagram, deployment instructions, and validation checks.'),('What to explore','Review domain services and replication, departmental SMB shares and access controls, Windows domain membership, and connectivity to the Apache intranet server.'),('Get started','Use the repository README to prepare the required Ludus templates, install the roles, load range-config.yml, and deploy. Follow its validation checklist before starting an exercise. The documented VM allocations total 36 GiB RAM, excluding host overhead.')]),
 dict(slug='range-days',title='EMP Range Days',repo='Ex-Machina-Parlor-Range-Days',category='Community / Range archive',summary='Range-day configurations, event records, and walkthroughs from Ex Machina Parlor, with a published EMP-FAK4 network diagram.',label='Event documentation',facts=[('Format','Range-day documentation'),('Documented configuration','EMP-FAK4'),('Starting point','Repository and network diagram')],sections=[('The range-day archive','The repository is described as a record of EMP range events and walkthroughs. Its current README introduces the EMP-FAK4 configuration and links to a range-day network diagram.'),('Explore the configuration','Start with the published diagram to understand the documented environment, then browse the repository for configuration files and any available event materials.'),('Participation','This page is a documentation entry point. The repository does not establish a current event schedule or a live range access endpoint.')]),
 dict(slug='hack-my-bot',title='Hack My Bot',repo='HackMyBot',category='Robotics / Wireless CTF',summary='A team-based robotics and wireless CTF combining robot piloting, hardware security, and a physical king-of-the-hill objective.',label='Competition format',facts=[('Team','Pilot + hacker'),('Arena','Physical king of the hill'),('Hardware','Tengu Marauder or an approved robot')],sections=[('The arena','The documented DEFCON Hack the Bots format places four teams in an obstacle-filled arena. A pilot drives the robot while a hacker works on the permitted wireless, IoT, and hardware challenges.'),('The objective','Reach the central platform, capture the physical flag, and defend the position. The arena design includes rotary and piston obstacles plus IoT-controlled barriers.'),('Rules and participation','Read the repository rules and event-specific RF requirements before participating. The rules prohibit permanent robot damage. The repository lists info@exmachinaparlor.net for participation questions; confirm current event availability with the organizers.')])
]

RANGES.insert(0, ROBOTICS)

def shell(title, body, prefix=''):
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Ex Machina Parlor</title><meta name="description" content="Explore Ex Machina Parlor cyber range projects, enterprise labs, range-day documentation, and robotics CTFs."><link rel="stylesheet" href="{prefix}assets/style.css"><meta name="theme-color" content="#101310"></head>
<body><header><div class="wrap nav"><a class="brand" href="{prefix}index.html"><b aria-hidden="true">EX</b><span>EX MACHINA PARLOR<small>CYBER RANGES</small></span></a><nav aria-label="Main navigation"><a href="{prefix}index.html#about">About EMP ranges</a><a href="{prefix}index.html#ranges">Attendee guides</a><a href="{prefix}index.html#resources">Resources</a><a href="{ORG}">GitHub ↗</a></nav></div></header><main class="wrap">{body}</main><footer><div class="wrap foot"><span>EX MACHINA PARLOR / LEARN THROUGH EXPLORATION</span><span>Public repository catalog · <a href="{ORG}">GitHub ↗</a></span></div></footer></body></html>'''

cards=''.join(f'''<article class="card"><span class="number">RANGE / 0{i}</span><span class="tag">{r['category'].upper()}</span><h3><a href="ranges/{r['slug']}.html">{r['title']}</a></h3><p>{r['summary']}</p><a class="go" href="ranges/{r['slug']}.html">Attendee guide <span aria-hidden="true">↗</span></a></article>''' for i,r in enumerate(RANGES,1))
resources=''.join(f'<a class="resource" href="{ORG}{repo}"><span>{name}<small>{desc}</small></span><span aria-hidden="true">↗</span></a>' for name,repo,desc in [('CTF resources','ctf-resources','A starting point for capture-the-flag resources.'),('Knightmare','Knightmare','A forked robotics and IoT security framework.'),('Presentations','Presentations','Conference talks and publications from the community.')])
home=f'''<div class="hero"><div><div class="eyebrow">EX MACHINA PARLOR / FIELD DIRECTORY 01</div><h1>Enter the range.<br><em>Build your edge.</em></h1><p class="intro">Hands-on security across enterprise networks, factories, robots, and drones. Explore what EMP builds and tests, then find your conference attendee guide.</p><a class="button" href="#ranges">Explore the ranges <span aria-hidden="true">↘</span></a></div><div class="map" role="img" aria-label="Illustrative lab topology connecting a gateway to domain services, workstations, and a web server"><div class="map-top"><span>LAB TOPOLOGY / AD RANGE</span><span>6 NODES</span></div><div class="network"><div class="node accent">RANGE GATEWAY</div><div class="stem"></div><div class="branches"><div class="node">VLAN 10<br>DC01 · DC02<br>FS01</div><div class="node">VLAN 20<br>WS01<br>WS02</div><div class="node">VLAN 30<br>WEB01</div></div></div><div class="map-caption">SCHEMATIC / BASED ON EMP-AD-RANGE</div></div></div><div class="strip"><span>04 RANGE GUIDES</span><span>ENTERPRISE NETWORKS</span><span>COMMUNITY RANGE DAYS</span><span>ROBOTICS & CTF</span></div>{ABOUT}<section id="ranges"><div class="section-head"><div><div class="eyebrow">04 / CHOOSE YOUR ENVIRONMENT</div><h2>Conference attendee guides</h2></div><p>Choose your range for an introduction, a suggested starting exercise, and what to ask the EMP crew before you begin.</p></div><div class="cards">{cards}</div><p class="note">Listed projects have public documentation. Live access, event schedules, and deployment readiness are not implied.</p></section><section id="resources" class="resources"><div><div class="eyebrow">05 / KEEP EXPLORING</div><h2>Beyond<br>the range.</h2><p class="note">Tools, reading, and community knowledge to support your next session.</p></div><div>{resources}</div></section>'''
(ROOT/'index.html').write_text(shell('Cyber ranges',home),encoding='utf-8')
for r in RANGES:
 sections=attendee_intro()
 sections+=''.join(f'<h2>{heading}</h2><p>{text}</p>' for heading,text in ATTENDEE.get(r['slug'], []))
 sections+=''.join(f'<h2>{heading}</h2><p>{text}</p>' for heading,text in r['sections'])
 if r['slug']=='robotics':
  sections+=robotics_zones()
 if r['slug']=='active-directory':
  rows=[('DC01 / DC02','Domain controllers','10','12 GiB'),('FS01','Department file server','10','6 GiB'),('WS01 / WS02','Windows 11 workstations','20','16 GiB'),('WEB01','Debian / Apache','30','2 GiB')]
  sections+='<h2>Environment at a glance</h2><div class="table-scroll"><table><thead><tr><th>Hosts</th><th>Role</th><th>VLAN</th><th>Total RAM</th></tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
 facts=''.join(f'<li><strong>{a}</strong>{b}</li>' for a,b in r['facts'])
 source_url=ORG+r['repo'] if r['repo'] else None
 source=(f'<a href="{source_url}#readme">{r["repo"]} README</a>' if source_url else 'Supplied robotics-cyber-range archive: README, architecture notes, and lab-zone documentation. This guide summarizes the example configuration; ask the crew which profile is deployed.')
 actions=(f'<a class="button secondary" href="{source_url}">Source repository ?</a>' if source_url else '')
 body=f'''<div class="breadcrumb"><a href="../index.html#ranges">Range directory</a> / {r['title']}</div><div class="detail-hero"><div class="eyebrow">{r['category']}</div><h1>{r['title']}</h1><p class="intro">{r['summary']}</p><a class="button" href="#attendee-start">Attendee check-in ?</a>{actions}</div><div class="detail-grid"><article>{sections}<p class="source">Source: {source}.</p></article><aside><div class="eyebrow">{r['label']}</div><h2>Range brief</h2><ul class="facts">{facts}</ul><p class="note">Ask the EMP range crew for current availability, access details, and the exercise running at this conference.</p></aside></div>'''
 (ROOT/'ranges'/f"{r['slug']}.html").write_text(shell(r['title'],body,'../'),encoding='utf-8')
print('Generated EMP homepage and 4 conference attendee guides.')
